// Normalización del payload entrante (Soporta Evolution API, Meta Cloud API o Webhook genérico)
const body = $input.item.json.body || $input.item.json;

let senderPhone = '';
let incomingText = '';
let senderName = 'Cliente';

if (body.data && body.data.message) {
  // Formato Evolution API / Baileys
  senderPhone = body.data.key.remoteJid.replace('@s.whatsapp.net', '');
  incomingText = body.data.message.conversation || body.data.message.extendedTextMessage?.text || '';
  senderName = body.data.pushName || 'Cliente';
} else if (body.entry && body.entry[0]?.changes?.[0]?.value?.messages?.[0]) {
  // Formato Meta Cloud API oficial
  const msg = body.entry[0].changes[0].value.messages[0];
  senderPhone = msg.from;
  incomingText = msg.text?.body || '';
  senderName = body.entry[0].changes[0].value.contacts?.[0]?.profile?.name || 'Cliente';
} else {
  senderPhone = body.from || body.phone || 'Unknown';
  incomingText = body.text || body.message || '';
  senderName = body.name || 'Cliente';
}

return {
  senderPhone,
  senderName,
  rawText: incomingText,
  normalizedText: incomingText.toLowerCase().trim()
};

